Here is the commit message:
hwmon: (powerz) Fix use-after-free on USB disconnect

After powerz_disconnect() frees the URB and releases the mutex, a
subsequent powerz_read() call can acquire the mutex and call
powerz_read_data(), which dereferences the freed URB pointer.

Fix by:
 - Setting priv->urb to NULL in powerz_disconnect() so that
   powerz_read_data() can detect the disconnected state.
 - Adding a !priv->urb check at the start of powerz_read_data()
   to return -ENODEV on a disconnected device.
 - Moving usb_set_intfdata() before hwmon registration so the
   disconnect handler can always find the priv pointer.

Fixes: 4381a36abdf1c ("hwmon: add POWER-Z driver")
Cc: stable@vger.kernel.org
Signed-off-by: Sanman Pradhan <psanman@juniper.net>
Link: https://lore.kernel.org/r/20260410002521.422645-2-sanman.pradhan@hpe.com
Signed-off-by: Guenter Roeck <linux@roeck-us.net>

Here is the root cause:
The disconnect function (powerz_disconnect) frees the URB but does not set the priv->urb pointer to NULL, leaving a dangling pointer. After releasing the mutex, a concurrent powerz_read call can acquire the mutex and invoke powerz_read_data, which dereferences the freed URB pointer, causing a use-after-free. Additionally, no NULL check exists in powerz_read_data to detect the freed state.

Here is the patch:

 static int powerz_read_data(struct usb_device *udev, struct powerz_priv *priv)
 {
 	int ret;

+	if (!priv->urb)
+		return -ENODEV;
+
 	priv->status = -ETIMEDOUT;
 	reinit_completion(&priv->completion);

 	priv->transfer_buffer[0] = 0x0c;
 	priv->transfer_buffer[1] = 0x00;
 	priv->transfer_buffer[2] = 0x02;
 	priv->transfer_buffer[3] = 0x00;

 	usb_fill_bulk_urb(priv->urb, udev,
 			  usb_sndbulkpipe(udev, POWERZ_EP_CMD_OUT),
 			  priv->transfer_buffer, 4, powerz_usb_cmd_complete,
 			  priv);
 	ret = usb_submit_urb(priv->urb, GFP_KERNEL);
 	if (ret)
 		return ret;

 	if (!wait_for_completion_interruptible_timeout
 	    (&priv->completion, msecs_to_jiffies(5))) {
 		usb_kill_urb(priv->urb);
 		return -EIO;
 	}

 	if (priv->urb->actual_length < sizeof(struct powerz_sensor_data))
 		return -EIO;

 	return priv->status;
 }


 static int powerz_probe(struct usb_interface *intf,
 			const struct usb_device_id *id)
 {
 	struct powerz_priv *priv;
 	struct device *hwmon_dev;
 	struct device *parent;

 	parent = &intf->dev;

 	priv = devm_kzalloc(parent, sizeof(*priv), GFP_KERNEL);
 	if (!priv)
 		return -ENOMEM;

 	priv->urb = usb_alloc_urb(0, GFP_KERNEL);
 	if (!priv->urb)
 		return -ENOMEM;
 	mutex_init(&priv->mutex);
 	init_completion(&priv->completion);

+	usb_set_intfdata(intf, priv);
+
 	hwmon_dev =
 	    devm_hwmon_device_register_with_info(parent, DRIVER_NAME, priv,
 						 &powerz_chip_info, NULL);
 	if (IS_ERR(hwmon_dev)) {
 		usb_free_urb(priv->urb);
 		return PTR_ERR(hwmon_dev);
 	}

-	usb_set_intfdata(intf, priv);
-
 	return 0;
 }

 static void powerz_disconnect(struct usb_interface *intf)
 {
 	struct powerz_priv *priv = usb_get_intfdata(intf);

 	mutex_lock(&priv->mutex);
 	usb_kill_urb(priv->urb);
 	usb_free_urb(priv->urb);
+	priv->urb = NULL;
 	mutex_unlock(&priv->mutex);
 }



